package controle;
import conexao.Conexao;import dao.TurmaDAO;import java.awt.*;import java.time.LocalTime;import javax.swing.*;import javax.swing.table.DefaultTableModel;import modelo.Turma;
public class TelaTurma extends JFrame{private final Conexao con=new Conexao();private TurmaDAO dao;private final JTextField id=new JTextField(),nome=new JTextField(),faixa=new JTextField(),dia=new JTextField(),hora=new JTextField(),cap=new JTextField(),treinador=new JTextField();private final DefaultTableModel m=new DefaultTableModel(new String[]{"Código","Nome","Faixa etária","Dia","Horário","Capacidade","Treinador"},0){public boolean isCellEditable(int r,int c){return false;}};private final JTable t=new JTable(m);public TelaTurma(){setTitle("Cadastro de Turma");setSize(850,500);setLocationRelativeTo(null);setDefaultCloseOperation(DISPOSE_ON_CLOSE);JPanel p=new JPanel(new GridLayout(7,2,5,5));id.setEditable(false);String[] l={"Código:","Nome:","Faixa etária:","Dia da semana:","Horário (HH:MM):","Capacidade:","Código treinador:"};JTextField[] f={id,nome,faixa,dia,hora,cap,treinador};for(int i=0;i<l.length;i++){p.add(new JLabel(l[i]));p.add(f[i]);}JPanel b=new JPanel();JButton novo=new JButton("Novo"),salvar=new JButton("Salvar"),excluir=new JButton("Excluir"),fechar=new JButton("Fechar");b.add(novo);b.add(salvar);b.add(excluir);b.add(fechar);novo.addActionListener(e->limpar());salvar.addActionListener(e->salvar());excluir.addActionListener(e->excluir());fechar.addActionListener(e->dispose());JPanel n=new JPanel(new BorderLayout());n.setBorder(BorderFactory.createEmptyBorder(10,10,10,10));n.add(p);n.add(b,BorderLayout.SOUTH);add(n,BorderLayout.NORTH);add(new JScrollPane(t));t.getSelectionModel().addListSelectionListener(e->{int r=t.getSelectedRow();if(r>=0&&!e.getValueIsAdjusting()){id.setText(m.getValueAt(r,0).toString());nome.setText(m.getValueAt(r,1).toString());faixa.setText(m.getValueAt(r,2).toString());dia.setText(m.getValueAt(r,3).toString());hora.setText(m.getValueAt(r,4).toString());cap.setText(m.getValueAt(r,5).toString());treinador.setText(m.getValueAt(r,6).toString());}});if(con.conecta()){dao=new TurmaDAO(con);carregar();}addWindowListener(new java.awt.event.WindowAdapter(){public void windowClosed(java.awt.event.WindowEvent e){con.desconecta();}});}private void carregar(){if(dao==null)return;try{m.setRowCount(0);for(Turma x:dao.listar())m.addRow(new Object[]{x.getIdTurma(),x.getNome(),x.getFaixaEtaria(),x.getDiaSemana(),x.getHorario(),x.getCapacidade(),x.getIdTreinador()});}catch(Exception e){erro(e);}}private void limpar(){for(JTextField x:new JTextField[]{id,nome,faixa,dia,hora,cap,treinador})x.setText("");}private void salvar(){try{Turma x=new Turma();x.setNome(nome.getText().trim());x.setFaixaEtaria(faixa.getText().trim());x.setDiaSemana(dia.getText().trim());x.setHorario(LocalTime.parse(hora.getText().trim()));x.setCapacidade(Integer.parseInt(cap.getText().trim()));x.setIdTreinador(Integer.parseInt(treinador.getText().trim()));if(id.getText().isBlank())dao.inserir(x);else{x.setIdTurma(Integer.parseInt(id.getText()));dao.atualizar(x);}carregar();limpar();}catch(Exception e){erro(e);}}private void excluir(){if(id.getText().isBlank())return;try{dao.excluir(Integer.parseInt(id.getText()));carregar();limpar();}catch(Exception e){erro(e);}}private void erro(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Erro",JOptionPane.ERROR_MESSAGE);}}
